class Solution {
public:
    int minMoves(vector<int>& nums) {
        int n = nums.size();
        int minVal = nums[0];
        long long sum = 0;
        for (int i = 0; i < n; ++i) {
            sum += nums[i];
            if (nums[i] < minVal) minVal = nums[i];
        }
        return (int)(sum - (long long)n * minVal);
    }
};
